package pl.zagranietyper;import org.junit.jupiter.api.Test;import pl.zagranietyper.repository.FootballSettlementRepository;import java.util.*;import java.util.concurrent.atomic.AtomicInteger;import static org.junit.jupiter.api.Assertions.*;
class FootballTeamFirstGoalReviewedSnapshotTest {@Test void immutableBoundaryIsExact(){assertEquals(67,FootballTeamFirstGoalReviewedSnapshot.APPROVED_IDS.size());assertEquals("206471f22e3049c857dd2c16b533df031e8cd035c60bfa1e6350236bcafa0c7e",FootballTeamFirstGoalReviewedSnapshot.EXPECTED_SHA256);}@Test void dryRunAndFailedGateNeverWrite(){AtomicInteger calls=new AtomicInteger();assertFalse(FootballTeamFirstGoalCoverageDryRunMain.parseApply(new String[0]));assertNull(FootballTeamFirstGoalCoverageDryRunMain.applyIfRequested(false,gate(true),List.of(),u->{calls.incrementAndGet();return success();}));assertThrows(IllegalStateException.class,()->FootballTeamFirstGoalCoverageDryRunMain.applyIfRequested(true,gate(false),List.of(),u->{calls.incrementAndGet();return success();}));assertEquals(0,calls.get());}@Test void successfulGateDelegatesToExactApply(){AtomicInteger calls=new AtomicInteger();assertEquals(67,FootballTeamFirstGoalCoverageDryRunMain.applyIfRequested(true,gate(true),List.of(),u->{calls.incrementAndGet();return success();}).updatedLegs());assertEquals(1,calls.get());}private static FootballTeamFirstGoalReviewedSnapshot.Gate gate(boolean p){return new FootballTeamFirstGoalReviewedSnapshot.Gate(67,40,27,0,"hash",1,Set.of(),Set.of(),p,p,p,p);}private static FootballSettlementRepository.ApplyResult success(){return new FootballSettlementRepository.ApplyResult(67,0,40,27,0,60,30,27,0,3,0);}}
